// ESM build registers every component and still allows tree-shaking
import * as bootstrap from 'bootstrap';
import 'bootstrap/dist/css/bootstrap.min.css';

// Tooltips are opt-in: the data attribute only marks the element
document.querySelectorAll('[data-bs-toggle="tooltip"]')
  .forEach((element) => new bootstrap.Tooltip(element));

// Bootstrap styles validity through the was-validated class on the form
document.querySelectorAll('form').forEach((form) => {
  form.addEventListener('submit', (event) => {
    if (!form.checkValidity()) {
      event.preventDefault();
      event.stopPropagation();
    }
    form.classList.add('was-validated');
  });
});

// The constructor accepts a selector or an element in Bootstrap 5.2 and later
const dialog = new bootstrap.Modal('#confirmDelete', {
  backdrop: 'static',
  keyboard: false,
});

dialog.show();

document.querySelector('#confirmDelete').addEventListener('hidden.bs.modal', () => {
  console.log('dialog closed');
});

// src/scss/app.scss: the with() clause sets Bootstrap defaults before they compile
@use "bootstrap/scss/bootstrap" with (
  $primary: #6f42c1,
  $border-radius: 0.5rem,
  $enable-shadows: true
);

// Project rules follow the framework import
.navbar-brand {
  letter-spacing: 0.02em;
}

/* Runtime theming: these variables inherit down the whole tree */
:root {
  --bs-body-font-family: "Inter", system-ui, sans-serif;
  --bs-body-bg: #f8f9fa;
  --bs-body-color: #212529;
  --bs-border-radius: 0.5rem;
  --bs-link-color: #6f42c1;
  --bs-link-hover-color: #59359a;
}

/* Buttons bake their colors into component variables, so target them directly */
.btn-primary {
  --bs-btn-bg: #6f42c1;
  --bs-btn-border-color: #6f42c1;
  --bs-btn-hover-bg: #59359a;
  --bs-btn-hover-border-color: #59359a;
  --bs-btn-active-bg: #4e2f88;
  --bs-btn-active-border-color: #4e2f88;
}

// Bootstrap reads data-bs-theme on <html> and recolors every component
const root = document.documentElement;
const prefersDark = matchMedia('(prefers-color-scheme: dark)').matches;
root.setAttribute('data-bs-theme', localStorage.getItem('theme') ?? (prefersDark ? 'dark' : 'light'));

document.querySelector('#theme-toggle').addEventListener('click', () => {
  const next = root.getAttribute('data-bs-theme') === 'dark' ? 'light' : 'dark';
  root.setAttribute('data-bs-theme', next);
  localStorage.setItem('theme', next);
});
